'use strict';

var unset = require( './../lib' );

// Unset a value at a shallow path:
var doc = {
	'a': 1,
	'b': 2
};
var out = unset( doc, [ 'a' ] );
console.log( out );
/* =>
    {
        'b': 2
    }
*/

// Unset a value at a deep path:
doc = {
	'a': {
		'b': {
			'c': 1,
			'd': 2
		}
	}
};
out = unset( doc, [ 'a', 'b', 'c' ] );
console.log( out );
/* =>
    {
        'a': {
            'b': {
                'd': 2
            }
        }
    }
*/

// Unset an element from an array:
doc = {
	'x': [ 'a', 'b', 'c' ]
};
out = unset( doc, [ 'x', '1' ] );
console.log( out );
/* =>
    {
        'x': [ 'a', 'c' ]
    }
*/

// Structural sharing (unchanged subtrees keep references):
doc = {
	'a': {
		'b': 1,
		'c': 2
	},
	'd': {
		'e': 3
	}
};
out = unset( doc, [ 'a', 'b' ] );
console.log( out.d === doc.d );
// => true
